return (function () {
  'use strict';
  /* Pure membership model; shared by the dashboard and verification. */
function buildMembershipModel(payloads) {
  const result = {rows: [], catalogs: {}, errors: [], excluded: 0, humanUsers: 0};
  const idKeys = {Users:'user_id', Roles:'role_id', Groups:'group_id'};
  for (const name of Object.keys(idKeys)) {
    const p = payloads[name], m = p?._metadata;
    if (!p || !Array.isArray(p.records) || !m ||
        !Number.isInteger(m.total_count) || m.page !== 0 ||
        m.total_count !== p.records.length) {
      result.errors.push(name + ': complete source data could not be verified. Refresh or ask an administrator to review source coverage.');
      continue;
    }
    const ids = p.records.map(r=>r[idKeys[name]]);
    if (ids.some(x=>!x) || new Set(ids).size !== ids.length)
      result.errors.push(name + ': missing or duplicate identifiers.');
    result.catalogs[name] = p.records;
  }
  if (result.errors.length) return result;
  const users = new Map(result.catalogs.Users.map(u=>[u.user_id,u]));
  result.humanUsers = result.catalogs.Users.filter(u=>['PERSON','EXTERNAL_PERSON'].includes(u.type)).length;
  const seen = new Set();
  for (const [source, kind, key] of [['Roles','Role','role_id'],['Groups','Group','group_id']]) {
    for (const membership of result.catalogs[source]) {
      // Empty memberships are omitted by JSONata and single members can arrive unwrapped.
      const refs = Array.isArray(membership.users) ? membership.users
        : membership.users == null ? [] : [membership.users];
      for (const ref of refs) {
        const uid = typeof ref === 'string' ? ref : ref?.user_id;
        const u = users.get(uid);
        if (!u) {
          result.errors.push(kind + ': a membership references a user absent from the complete directory.');
          continue;
        }
        if (!['PERSON','EXTERNAL_PERSON'].includes(u.type)) { result.excluded++; continue; }
        const unique = JSON.stringify([uid,kind,membership[key]]);
        if (seen.has(unique)) continue;
        seen.add(unique);
        result.rows.push({
          userId:uid, membershipId:membership[key], kind,
          userName:u.full_name || [u.first_name,u.last_name].filter(Boolean).join(' ') || u.principal_id || 'Unknown',
          login:u.principal_id || 'Unknown', email:u.email || 'Unknown',
          status:u.status || 'Unknown', membership:kind + ': ' + membership.name,
          grantDate:'Unknown'
        });
      }
    }
  }
  result.errors = [...new Set(result.errors)];
  if (result.errors.length) result.rows = []; // Never publish an incomplete report as complete.
  result.rows.sort((a,b)=>a.userName.localeCompare(b.userName)||a.login.localeCompare(b.login)||a.membership.localeCompare(b.membership));
  return result;
}
function filterMembershipRows(rows, state) {
  const q = (state.query || '').trim().toLowerCase();
  return rows.filter(r =>
    (state.kind === 'All' || state.kind === r.kind) &&
    (state[r.kind] === null || state[r.kind].includes(r.membershipId)) &&
    (!q || [r.userName,r.login,r.email,r.status,r.membership].some(v=>v.toLowerCase().includes(q))));
}
function membershipCsv(rows) {
  const safe = v => '"' + String(v ?? '').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""') + '"';
  return [
    ['User Name','Login ID','Email','Profile Status','Group / Roles','Grant Date'],
    ...rows.map(r=>[r.userName,r.login,r.email,r.status,r.membership,r.grantDate])
  ].map(row=>row.map(safe).join(',')).join('\r\n');
}

  const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const payloads = {};
  const frameRows = Array.isArray(data) ? data : data && Array.isArray(data.data) ? data.data : [];
  for (const row of frameRows) for (const name of ['Users','Roles','Groups']) {
    const value=row[name] ?? row[name+' · '+name];
    if (value) { try { payloads[name] = JSON.parse(value); } catch (_) {} }
  }
  const model = buildMembershipModel(payloads);
  const signature = JSON.stringify(payloads);
  const key = '__helixItomMembershipState';
  const state = window[key] || (window[key] = {Role:null,Group:null,kind:'All',query:'',page:0});
  const header = `<header class="im-header"><div><div class="im-eyebrow">ITOM / ACCESS REVIEW</div><h1>Roles &amp; group memberships</h1><p>One entry per direct role assignment or group membership.</p></div><div class="im-logo"><img alt="BMC Helix" width="155" src="data:image/svg+xml;base64,"></div></header>`;
  function catalog(kind) {
    const source = kind === 'Role' ? 'Roles' : 'Groups', id = kind === 'Role' ? 'role_id':'group_id';
    const entries = [...model.catalogs[source]].sort((a,b)=>a.name.localeCompare(b.name));
    return `<details class="im-picker" data-kind="${kind}"><summary>ITOM ${source} · <span data-selection="${kind}">All</span></summary>
      <div class="im-dropdown"><input type="search" data-search="${kind}" aria-label="Find ${source.toLowerCase()}" placeholder="Find ${source.toLowerCase()}…">
      <label class="im-choice"><input type="checkbox" data-kind="${kind}" value="__all" ${state[kind]===null?'checked':''}>All ${source.toLowerCase()}</label>
      <div class="im-choices">${entries.map(m=>`<label class="im-choice" data-name="${esc(m.name.toLowerCase())}"><input type="checkbox" data-kind="${kind}" value="${esc(m[id])}" ${state[kind]?.includes(m[id])?'checked':''}>${esc(m.name)}</label>`).join('')}</div></div></details>`;
  }
  function markup() {
    if (model.errors.length) return `<section class="im-root im-shell">${header}<div class="im-error" role="alert"><h2>Membership report unavailable</h2>${model.errors.map(e=>`<p>${esc(e)}</p>`).join('')}<p>No partial membership list is shown.</p></div></section>`;
    return `<section class="im-root im-shell">${header}<div class="im-content">
      <div class="im-summary"><div><strong>${new Set(model.rows.map(r=>r.userId)).size}</strong><span>Users with memberships</span></div>
      <div><strong>${model.rows.length}</strong><span>Direct membership entries</span></div>
      <div><strong>${model.catalogs.Roles.length} / ${model.catalogs.Groups.length}</strong><span>Roles / groups available</span></div>
      <div class="im-coverage"><b>Complete source lists</b><span>${model.humanUsers} console user profiles checked</span></div></div>
      <div class="im-filters">${catalog('Group')}${catalog('Role')}
      <label class="im-mode">Show<select aria-label="Membership type"><option>All</option><option>Role</option><option>Group</option></select></label>
      <label class="im-search">Find a user or membership<input type="search" aria-label="Find a user or membership" placeholder="Name, login, email, status or membership…" value="${esc(state.query)}"></label>
      <button type="button" data-action="reset">Reset to All</button></div>
      <p class="im-note">All lists every direct membership. Roles inherited through groups are excluded. Console users only; API identities are excluded. Grant Date is Unknown because assignment dates are not supplied by these sources.</p>
      <div class="im-table-heading"><h2>Membership entries</h2><span class="im-result" aria-live="polite"></span><button type="button" data-action="csv">Download filtered CSV</button></div>
      <div class="im-table-wrap"><table aria-label="ITOM user memberships"><thead><tr>${['User Name','Login ID','Email','Profile Status','Group / Roles','Grant Date'].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody></tbody></table></div>
      <div class="im-pagination"><button type="button" data-action="prev">Previous</button><span class="im-page"></span><button type="button" data-action="next">Next</button></div>
      <details class="im-about"><summary>How to read this report</summary><p>Role selections filter role rows; group selections filter group rows. Their matching entries are combined. Use Show to view only roles or only groups. Users without direct memberships have no entry.</p><p>Current membership snapshot; the dashboard time range does not apply. Refresh reloads all three source lists. Completeness is checked against each source's reported total before displaying results. CSV includes all filtered entries, across every display page.</p></details>
      </div></section>`;
  }
  handlebars.registerHelper('itomMemberships',()=>new handlebars.SafeString(markup()));
  const timers=[];
  function bind() {
    const root=document.querySelector('.im-root');
    if(!root || model.errors.length || root.__imSignature===signature) return;
    root.__imSignature=signature;
    if(root.__imAbort) root.__imAbort.abort();
    // Dynamic Text sanitises form inputs in Handlebars output. Mount the
    // authored, escaped interactive UI in its supported JavaScript lifecycle.
    const mounted=document.createElement('div');
    mounted.innerHTML=markup();
    root.innerHTML=mounted.firstElementChild.innerHTML;
    const abort=new AbortController(); root.__imAbort=abort;
    const opts={signal:abort.signal};
    const size=50;
    function render() {
      const rows=filterMembershipRows(model.rows,state);
      const pages=Math.max(1,Math.ceil(rows.length/size));
      state.page=Math.max(0,Math.min(state.page,pages-1));
      root.querySelector('tbody').innerHTML=rows.length?rows.slice(state.page*size,(state.page+1)*size).map(r=>`<tr><td>${esc(r.userName)}</td><td>${esc(r.login)}</td><td>${esc(r.email)}</td><td><span class="im-status">${esc(r.status)}</span></td><td>${esc(r.membership)}</td><td class="im-unknown">Unknown</td></tr>`).join(''):'<tr><td colspan="6" class="im-empty">No memberships match these filters.</td></tr>';
      root.querySelector('.im-result').textContent=`${rows.length} entries · ${new Set(rows.map(r=>r.userId)).size} users`;
      root.querySelector('.im-page').textContent=`Page ${state.page+1} of ${pages}`;
      root.querySelector('[data-action="prev"]').disabled=state.page===0;
      root.querySelector('[data-action="next"]').disabled=state.page===pages-1;
      root.querySelector('[data-action="csv"]').disabled=!rows.length;
      root.querySelector('select').value=state.kind;
      for(const kind of ['Role','Group']) {
        root.querySelector(`[data-selection="${kind}"]`).textContent=state[kind]===null?'All':`${state[kind].length} selected`;
        root.querySelectorAll(`input[type="checkbox"][data-kind="${kind}"]`).forEach(el=>el.checked=el.value==='__all'?state[kind]===null:!!state[kind]?.includes(el.value));
      }
    }
    root.addEventListener('change',e=>{
      const el=e.target;
      if(el.matches('input[type="checkbox"]')) {
        const k=el.dataset.kind;
        if(el.value==='__all') state[k]=el.checked?null:[];
        else {const set=new Set(state[k]||[]);el.checked?set.add(el.value):set.delete(el.value);state[k]=[...set];}
      } else if(el.matches('select')) state.kind=el.value;
      else return;
      state.page=0;render();
    },opts);
    root.addEventListener('input',e=>{
      const el=e.target;
      if(el.dataset.search) {
        const q=el.value.trim().toLowerCase();
        el.closest('.im-dropdown').querySelectorAll('[data-name]').forEach(x=>x.hidden=!x.dataset.name.includes(q));
      } else if(el.matches('.im-search input')) {state.query=el.value;state.page=0;render();}
    },opts);
    root.addEventListener('click',e=>{
      const action=e.target.closest('[data-action]')?.dataset.action;
      if(!action)return;
      if(action==='reset') {
        Object.assign(state,{Role:null,Group:null,kind:'All',query:'',page:0});
        root.querySelectorAll('input[type="search"]').forEach(el=>el.value='');
        root.querySelectorAll('[data-name]').forEach(el=>el.hidden=false);
      }
      if(action==='prev')state.page--;
      if(action==='next')state.page++;
      if(action==='csv') {
        const url=URL.createObjectURL(new Blob(['\ufeff'+membershipCsv(filterMembershipRows(model.rows,state))],{type:'text/csv;charset=utf-8'}));
        const a=document.createElement('a');a.href=url;a.download='itom-user-memberships.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
      }
      render();
    },opts);
    render();
  }
  [0,80,250,700,1600].forEach(ms=>timers.push(setTimeout(bind,ms)));
  return ()=>{timers.forEach(clearTimeout);handlebars.unregisterHelper('itomMemberships');};
})();

